    assert_eq!(aliases, ["Current company alias", "Current company name"]);
    assert_eq!(
        sqlx::query_scalar!(
            "SELECT funder_id FROM exposed.funding_entries WHERE source_declaration_id = 4"
        )
        .fetch_one(&pool)
        .await?,
        Some(shared.id)
    );
    assert!(
        sqlx::query!("SELECT id FROM exposed.funders WHERE id = $1", old_local)
            .fetch_optional(&pool)
            .await?
