    );
    assert_eq!(
        sqlx::query_scalar!(
            "SELECT count(*) FROM exposed.funders AS funder WHERE NOT EXISTS (SELECT 1 FROM exposed.funding_entries AS entry WHERE entry.funder_id = funder.id)"
        )
        .fetch_one(&pool)
